items=[]
for mid,n in notes.items():
 p=F/'稿件'/f'{mid}.md';lines=p.read_text().splitlines();heads=[(i,l) for i,l in enumerate(lines,1) if l.startswith('#')];sources=[i for i,l in enumerate(lines,1) if l.startswith('E') or '**E' in l]
 # Headings are navigation anchors, evidence scope includes full section, reviewed in full.
 def anchor(k):
  targets=([1], [h[0] for h in heads if any(t in h[1] for t in ['机制','判断','完整','一次','构造','连接','实质'])], [h[0] for h in heads if any(t in h[1] for t in ['构造','完整','回返','结果','实例'])], [h[0] for h in heads if any(t in h[1] for t in ['构造','完整','实际','一次'])], [h[0] for h in heads if any(t in h[1] for t in ['失败','反例','误用','场景'])], sources, [h[0] for h in heads if any(t in h[1] for t in ['交接','输出','依据','证据'])])[k]
  return targets[0] if targets else (heads[min(1,len(heads)-1)][0])
 ds=[]
 for k,note in enumerate(n):
  partial=k==1 and mid in ['WB01','WB02','WB04','WB05','WB06']
  ds.append({'dimension':dims[k],'assessment':'局部' if partial else '充分','evidence':{'path':str(p),'line':anchor(k),'scope':'该节及其后相关表/反例；具体审核判断见reason'},'reason':note})
 items.append({'method_id':mid,'candidate_path':str(p),'sha256':sha(p),'candidate_version':'0.1.0','seven_dimensions':ds,'disposition':'content_candidate_pass','allowed_scope':'限定原典选段＋原创平台教学内容候选，不是完整专著算法重建/真实工程采用/上线批准','review_report':str(P/'审核结论.md'),'revision_review':str(P/'修订复核状态.json')})
assert len(items)==24
